import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyBaoTri = () => {
    const now = new Date();
    const [selectedDate, setSelectedDate] = useState(now.getDate());
    const [selectedMonth, setSelectedMonth] = useState(now.getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(now.getFullYear());

    const [loading, setLoading] = useState(false);
    const [requests, setRequests] = useState([]);

    useEffect(() => {
        fetchData();
    }, [selectedDate, selectedMonth, selectedYear]);

    const fetchData = () => {
        setLoading(true);
        // Tối ưu: Đọc trực tiếp từ database chung (localStorage)
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const filtered = allData.filter(item => 
            item.day === selectedDate && 
            item.month === selectedMonth && 
            item.year === selectedYear
        );
        setTimeout(() => {
            setRequests(filtered); 
            setLoading(false);
        }, 300);
    };

    const updateStatus = (id, newStatus) => {
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const updated = allData.map(req => req.id === id ? { ...req, status: newStatus } : req);
        localStorage.setItem('maintenance_db', JSON.stringify(updated));
        fetchData(); // Cập nhật lại giao diện
    };

    const getStatusStyle = (status) => {
        switch (status) {
            case 'pending': return { color: '#dc3545', bg: '#f8d7da' };
            case 'processing': return { color: '#856404', bg: '#fff3cd' };
            case 'completed': return { color: '#155724', bg: '#d4edda' };
            default: return { color: '#333', bg: '#eee' };
        }
    };

    return (
        <div style={adminContainer}>
            <div style={adminHeader}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '22px' }}>🛠 QUẢN LÝ YÊU CẦU BẢO TRÌ</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedDate} onChange={(e) => setSelectedDate(Number(e.target.value))} style={selectStyle}>
                        {Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>Ngày {i+1}</option>)}
                    </select>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(Number(e.target.value))} style={selectStyle}>
                        {Array.from({length:12},(_,i)=><option key={i+1} value={i+1}>Tháng {i+1}</option>)}
                    </select>
                </div>
            </div>

            <div style={tableWrapperGlass}>
                <div style={tableContent}>
                    {loading ? (
                        <div style={loadingText}>ĐANG TRUY XUẤT DỮ LIỆU...</div>
                    ) : requests.length > 0 ? (
                        <table style={tableStyle}>
                            <thead style={theadStyle}>
                                <tr>
                                    <th style={thStyle}>PHÒNG</th>
                                    <th style={thStyle}>NỘI DUNG SỰ CỐ</th>
                                    <th style={thStyle}>THỜI GIAN</th>
                                    <th style={thStyle}>TRẠNG THÁI</th>
                                </tr>
                            </thead>
                            <tbody>
                                {requests.map((req) => {
                                    const style = getStatusStyle(req.status);
                                    return (
                                        <tr key={req.id} style={trStyle}>
                                            <td style={tdRoom}>{req.room}</td>
                                            <td style={tdIssue}>
                                                <div style={{fontWeight:'bold'}}>{req.title}</div>
                                                <div style={{fontSize:'12px', color:'#666'}}>{req.issue}</div>
                                            </td>
                                            <td style={tdTime}>{req.time}</td>
                                            <td style={tdStyle}>
                                                <select 
                                                    value={req.status} 
                                                    onChange={(e) => updateStatus(req.id, e.target.value)}
                                                    style={{ ...statusSelect, backgroundColor: style.bg, color: style.color }}
                                                >
                                                    <option value="pending">⏳ Chờ xử lý</option>
                                                    <option value="processing">🛠 Đang xử lý</option>
                                                    <option value="completed">✅ Hoàn thành</option>
                                                </select>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    ) : (
                        <div style={emptyAdmin}>📅 Không có yêu cầu nào.</div>
                    )}
                </div>
            </div>
        </div>
    );
};

// --- STYLES ADMIN ---
const adminContainer = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const adminHeader = { padding: '20px 30px', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backdropFilter: 'blur(10px)' };
const tableWrapperGlass = { flex: 1, padding: '25px', display: 'flex', justifyContent: 'center', overflow: 'hidden' };
const tableContent = { width: '100%', maxWidth: '1100px', background: 'rgba(255, 255, 255, 0.85)', backdropFilter: 'blur(15px)', borderRadius: '25px', overflowY: 'auto', boxShadow: '0 8px 32px rgba(0,0,0,0.3)' };
const tableStyle = { width: '100%', borderCollapse: 'collapse' };
const theadStyle = { background: 'rgba(0,0,0,0.05)', textAlign: 'left', position: 'sticky', top: 0 };
const thStyle = { padding: '20px', color: '#8b5e5e' };
const trStyle = { borderBottom: '1px solid rgba(0,0,0,0.05)' };
const tdStyle = { padding: '20px' };
const tdRoom = { ...tdStyle, fontWeight: '800', fontSize: '20px' };
const tdIssue = { ...tdStyle, color: '#444' };
const tdTime = { ...tdStyle, color: '#888', fontSize: '14px' };
const statusSelect = { padding: '8px 12px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' };
const selectStyle = { padding: '8px 12px', borderRadius: '12px', border: 'none', background: '#fff', fontWeight: 'bold' };
const loadingText = { textAlign: 'center', padding: '100px', fontWeight: 'bold', color: '#8b5e5e' };
const emptyAdmin = { textAlign: 'center', padding: '100px', color: '#999' };

export default QuanLyBaoTri;
